import {
  Component,
  h,
  Prop,
  Element,
  // Fragment,
  ComponentInterface,
  State,
  Host,
  EventEmitter,
  Event,
} from '@stencil/core';
import classnames from 'classnames';
import { UploadFile, UploadChangeParam, BeforeUploadHook } from '../ks-upload/types';
// import { uploadMessages } from '@fe-infra/keystone-locales';
import { getBase64, IUploadOption } from '../ks-upload/utils';
// import { t } from '@src/shared/i18n';
import { logger } from '@src/shared/unclassified/logger';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import { KsIconDelete, KsIconPlusSmall } from '@fe-infra/keystone-icons-stencil';

const prefix = 'upload-media';

@Component({
  tag: 'ks-upload-media',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsUploadMedia implements ComponentInterface {
  private uploadEl?: HTMLKsUploadElement;

  @Element() el!: HTMLKsUploadMediaElement;

  /** The status of the upload component. */
  @Prop() @FormContextValueReconcile() status?: 'default' | 'error';
  /** The size of the upload component. */
  @Prop() size?: 'lg' | 'md' | 'sm' | 'xs' = 'lg';
  /** The accepted file types for upload, similar to the HTML `accept` attribute. */
  @Prop() accept = '.png,.jpg,.svg,.gif,.mp4,.mov,.avi,.wmv,.m4v';
  /** The URL where the files will be uploaded. */
  @Prop() action?: string;

  /** Additional data sent with the upload request. */
  @Prop() data?: object;
  /** The name attribute value for the files in the upload request, sent to the backend. */
  @Prop() name = 'file';
  /** Disables the upload component, preventing file selection or drag-and-drop functionality. */
  @Prop() @FormContextValueReconcile() disabled = false;

  /** The headers to be sent along with the upload request. */
  @Prop() headers?: object;
  /** The HTTP method used for the upload request. */
  @Prop() method = 'post';
  /** The current list of files in the upload queue. */
  @Prop() @FormContextValueReconcile({ contextKey: 'valueFromContext' }) fileList?: UploadFile[];
  /** The default file list when the component is first rendered. */
  @Prop() defaultFileList: UploadFile[] = [];
  /** Description related to the upload, such as the types of uploads allowed. */
  @Prop() description = '';
  /** Specifies how the preview image/video should be resized to fit its container. */
  @Prop() objectFit: 'cover' | 'contain' = 'contain';
  /** A function to be called before the upload process begins, can be used to validate files. */
  @Prop() beforeUpload?: BeforeUploadHook;
  /** A function to be called before a file is removed from the upload queue. */
  @Prop() beforeRemove?: (file: UploadFile & { detail: UploadFile }) => boolean | Promise<boolean>;
  /** Allows custom control of the upload process, overriding the default request behavior. */
  @Prop() customRequest?: (option: IUploadOption) => void;
  /** Custom event emitted when the file list or upload state changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<UploadChangeParam<UploadFile>>;
  /** Custom event emitted when the file upload state errors. */
  @Event({ bubbles: false, composed: false }) ksError!: EventEmitter<UploadChangeParam<UploadFile>>;

  @State() file?: UploadFile;

  @State() previewUrl = '';

  @State() highlight = false;

  @State() isError = false;

  private isInternalPreview = false;

  private clearPreview() {
    if (this.isInternalPreview && this.previewUrl && this.previewUrl.startsWith('blob:')) {
      URL.revokeObjectURL(this.previewUrl);
    }
    this.previewUrl = '';
    this.isInternalPreview = false;
  }

  private async isVideo(file?: UploadFile): Promise<boolean> {
    if (!file) return false;
    if (file.type?.startsWith('video/')) return true;

    // Check extension from URL or name
    const urlOrName = file.url || file.thumbUrl || file.name || '';
    if (!urlOrName) return false;

    // Remove query parameters and hash if it's a URL
    const cleanUrl = urlOrName.split('?')[0]?.split('#')[0] || '';

    // Comprehensive list of common video extensions
    if (/\.(mp4|webm|ogg|mov|avi|wmv|flv|mkv|m4v|3gp)$/i.test(cleanUrl)) {
      return true;
    }

    // If it's a URL but doesn't have a known extension, try fetching headers
    if (file.url || file.thumbUrl) {
      try {
        const targetUrl = file.url || file.thumbUrl;
        if (!targetUrl) return false;

        const response = await fetch(targetUrl, { method: 'HEAD' });
        const contentType = response.headers.get('content-type');
        if (contentType && contentType.startsWith('video/')) {
          return true;
        }
      } catch (e) {
        // Fallback to false if fetch fails (e.g., CORS)
        return false;
      }
    }

    return false;
  }

  @State() private isVideoFile = false;

  async componentWillLoad() {
    const list = this.fileList !== undefined ? this.fileList : this.defaultFileList;
    if (list && list.length > 0) {
      const file = list[0];
      if (!file) return;
      this.file = file;
      this.isVideoFile = await this.isVideo(file);

      if (file.url || file.thumbUrl) {
        this.previewUrl = file.url || file.thumbUrl || '';
        this.isInternalPreview = false;
      } else if (file.originFileObj) {
        if (this.isVideoFile) {
          this.previewUrl = URL.createObjectURL(file.originFileObj);
          this.isInternalPreview = true;
        } else {
          this.previewUrl = await getBase64(file.originFileObj);
          this.isInternalPreview = false;
        }
      }
    }
  }

  private handleChange = async (event: CustomEvent) => {
    if (this.disabled) return;
    const { detail } = event;
    const { error } = detail;
    this.highlight = false;
    if (error) {
      logger?.error(error);
      this.isError = true;
      this.ksError.emit(event.detail);
      return;
    }
    this.isError = false;
    if (this.file?.uid !== event.detail.file.uid) {
      this.clearPreview();
    }

    this.file = event.detail.file;

    if (this.file) {
      this.isVideoFile = await this.isVideo(this.file);
    }

    if (this.file && !this.previewUrl) {
      if (this.file.url || this.file.thumbUrl) {
        this.previewUrl = this.file.url || this.file.thumbUrl || '';
        this.isInternalPreview = false;
      } else if (this.file.originFileObj) {
        if (this.isVideoFile) {
          this.previewUrl = URL.createObjectURL(this.file.originFileObj);
          this.isInternalPreview = true;
        } else {
          this.previewUrl = await getBase64(this.file.originFileObj);
          this.isInternalPreview = false;
        }
      }
    }

    if (event.detail.file.status === 'removed') {
      // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
      this.file = null;
      this.clearPreview();
    }

    this.ksChange.emit?.(event.detail);
  };

  private handleDelete = (e: PointerEvent) => {
    e.stopPropagation();
    this.file && this.uploadEl?.handleRemove(this.file);
  };

  private handleDragOver(e: DragEvent) {
    e.preventDefault();
    if (this.disabled) return;
    this.highlight = true;
  }

  private handleDragLeave() {
    this.highlight = false;
  }

  private handleDrop = () => {
    this.highlight = false;
  };

  private pointerEnterVideo = (e: PointerEvent) => {
    const video = e.target as HTMLVideoElement;
    video.play().catch((err) => console.warn('Autoplay prevented:', err));
  };

  private pointerLeaveVideo = (e: PointerEvent) => {
    const video = e.target as HTMLVideoElement;
    video.pause();
  };

  disconnectedCallback() {
    this.clearPreview();
  }

  private renderState = () => {
    const { percent = 10, status } = this.file || {};
    if (status === 'uploading') {
      const radius = 7.5;
      const circumference = 2 * Math.PI * radius;
      const offset = circumference - (percent / 100) * circumference;

      return (
        <div class={`${prefix}__progressContainer`}>
          <svg xmlns="http://www.w3.org/2000/svg" width="19" height="19" viewBox="0 0 19 19" fill="none">
            <circle
              cx="9.5"
              cy="9.5"
              r={radius}
              stroke="url(#paint0_linear_164435_9478)"
              stroke-width="1.5"
              fill="none"
              stroke-linecap="round"
              stroke-dasharray={circumference}
              stroke-dashoffset={offset}
              transform="rotate(-90 9.5 9.5)"
            />
            <defs>
              <linearGradient
                id="paint0_linear_164435_9478"
                x1="0.747315"
                y1="17.9194"
                x2="0.747314"
                y2="-12.9932"
                gradientUnits="userSpaceOnUse"
              >
                <stop stop-color="#31BDB8" />
                <stop offset="0.5" stop-color="#95AEFE" />
                <stop offset="0.995" stop-color="#A1A1FA" />
              </linearGradient>
            </defs>
          </svg>
        </div>
      );
    }
    if (status === 'done') {
      return (
        <div class={classnames(`${prefix}__action`)} onClick={this.handleDelete}>
          <KsIconDelete size={14} class={`${prefix}__action-close`} data-testid="ks-upload-media-index-eKqsJe" />
        </div>
      );
    }
    return null;
  };

  render() {
    const { status } = this.file || {};
    return (
      <Host class="KsUploadImage">
        <ks-upload
          ref={(el) => (this.uploadEl = el)}
          accept={this.accept}
          action={this.action}
          data={this.data}
          name={this.name}
          disabled={this.disabled}
          multiple={false}
          headers={this.headers}
          method={this.method}
          fileList={this.fileList}
          defaultFileList={this.defaultFileList}
          showUploadList={false}
          maxCount={{ value: 1, behavior: 'replace' }}
          beforeRemove={this.beforeRemove}
          beforeUpload={this.beforeUpload}
          customRequest={this.customRequest}
          onKsChange={this.handleChange}
          description={this.description}
          data-testid="ks-upload-media-index-fbq3jt"
        >
          <div
            onDragEnter={(e) => this.handleDragOver(e)}
            onDragOver={(e) => this.handleDragOver(e)}
            onDragLeave={() => this.handleDragLeave()}
            onDrop={this.handleDrop}
            class={classnames(
              prefix,
              `${prefix}--plain`,
              `${prefix}--${this.size}`,
              { [`${prefix}--disabled`]: this.disabled },
              this.isError || this.status === 'error' ? `${prefix}--error` : '',
              this.highlight ? `${prefix}--highlight` : '',
            )}
            data-testid="ks-upload-media-index-fAyCCs"
          >
            {status !== 'uploading' && !this.previewUrl && <KsIconPlusSmall size={16} />}

            {this.previewUrl && status !== 'uploading' && (
              <div class={classnames(`${prefix}__picture`, { [`${prefix}__picture--video`]: this.isVideoFile })}>
                {this.isVideoFile ? (
                  <video
                    src={this.previewUrl}
                    loop
                    muted
                    playsinline
                    style={{ objectFit: this.objectFit }}
                    onPointerEnter={this.pointerEnterVideo}
                    onPointerLeave={this.pointerLeaveVideo}
                  />
                ) : (
                  <img src={this.previewUrl} style={{ objectFit: this.objectFit }} alt="" />
                )}
              </div>
            )}

            {this.renderState()}
          </div>
        </ks-upload>
      </Host>
    );
  }
}
